#include <bits/stdc++.h>
// Deterministic finite-image audit for the [4,9,3] Coxeter sector.
// No random choices or floating point are used. The final line is
// ORDER 11985408, equal to |Omega^+_4(F_17)|.
using namespace std; const int P=17; using I128=unsigned __int128;
struct U{I128 z; bool operator==(U const&o)const{return z==o.z;}};
struct H{size_t operator()(U const&a)const{unsigned long long lo=(unsigned long long)a.z,hi=(unsigned long long)(a.z>>64); return lo ^ (hi*0x9e3779b97f4a7c15ULL);}};
U enc(const uint8_t *a){ I128 z=0,m=1; for(int i=0;i<16;i++){z+=m*a[i];m*=P;}return{z};}
void dec(U A,uint8_t*a){I128 z=A.z;for(int i=0;i<16;i++){a[i]=z%P;z/=P;}}
U mul(U A,U B){uint8_t a[16],b[16],c[16];dec(A,a);dec(B,b);for(int i=0;i<4;i++)for(int j=0;j<4;j++){int s=0;for(int k=0;k<4;k++)s+=a[4*i+k]*b[4*k+j];c[4*i+j]=s%P;}return enc(c);}
int main(){uint8_t I[16]={};for(int i=0;i<4;i++)I[4*i+i]=1;int q[4][4]={{0,6,0,0},{6,0,3,0},{0,3,0,1},{0,0,1,0}};vector<U>R;for(int i=0;i<4;i++){uint8_t a[16];memcpy(a,I,16);for(int j=0;j<4;j++)a[4*i+j]=(i==j?16:q[i][j]);R.push_back(enc(a));}
// W^+ is generated by all pair products R_i R_j (i<j).
vector<U>G;for(int i=0;i<4;i++)for(int j=i+1;j<4;j++)G.push_back(mul(R[i],R[j]));unordered_set<U,H>S;S.reserve(13000000);vector<U>v;v.reserve(12000000);U id=enc(I);S.insert(id);v.push_back(id);for(size_t qi=0;qi<v.size();qi++){if(qi%1000000==0)cerr<<qi<<"/"<<v.size()<<"\n";U x=v[qi];for(U g:G){U y=mul(x,g);if(S.insert(y).second)v.push_back(y);}}cerr<<"ORDER "<<v.size()<<"\n";}
